// 1. Extrai a resposta bruta do Diretor de Arte
const dadosArte = Array.isArray($input.all()[0].json) ? $input.all()[0].json[0] : $input.all()[0].json;
const textoBruto = dadosArte?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!textoBruto) throw new Error("Resposta do Diretor de Arte inválida.");

// Limpa e faz o parse do JSON do Diretor de Arte
let jsonLimpo = textoBruto.trim().replace(/^```json/, "").replace(/```$/, "").trim();
const iArte = JSON.parse(jsonLimpo);

// 2. Monta o objeto contendo estritamente a capa e as imagens internas escolhidas
const imagensGeradas = {
    "img-1": iArte.prompt_capa
};

if (iArte.imagens_internas && Array.isArray(iArte.imagens_internas)) {
    iArte.imagens_internas.forEach(img => {
        // A foto após o bloco N equivale a img-(N+1)
        const chaveImg = `img-${img.numero_do_bloco_alvo + 1}`;
        imagensGeradas[chaveImg] = img.prompt_em_ingles;
    });
}

// 3. Retorna APENAS a estratégia e os prompts, zerando qualquer texto do post
return [{
    json: {
        estrategia_visual: iArte.estrategia_visual_e_orcamento,
        prompts_de_imagens: imagensGeradas
    }
}];

// 1. Pega os prompts de imagem do nó anterior
const item = $input.first();
if (!item || !item.json || !item.json.prompts_de_imagens) {
    throw new Error("A estrutura 'prompts_de_imagens' não foi encontrada na entrada.");
}

const prompts = item.json.prompts_de_imagens;

// 2. Puxa o ID estritamente do nó "Image Generator" direto do body
const dadosWebhook = $('Image Generator').first().json;
const postId = dadosWebhook?.body?.payload_para_api?.output?.pt?.id || "ID_NAO_ENCONTRADO";

const filaDeImagens = [];

// 3. Varre as chaves de imagem e monta o payload individual para o loop
for (const key in prompts) {
    if (key.startsWith('img-')) {
        // Extrai o número da posição (1 = hero, 2 = bloco 1, etc.)
        const numeroPosicao = parseInt(key.replace('img-', ''), 10);

        filaDeImagens.push({
            json: {
                post_id: postId,         // ID puxado do body do webhook
                position: numeroPosicao, // Posição numérica da imagem
                image: prompts[key]      // O prompt fotorrealista em inglês
            }
        });
    }
}

// 4. Retorna a fila dividida para a Vertex AI processar item por item
return filaDeImagens;

