function converterHtmlParaTextoTts(titulo, blocosHtml) {
  // Unifica todos os blocos HTML em uma única string
  let html = blocosHtml.join("\n\n");

  // Função auxiliar inteligente para substituir blocos <div> respeitando o aninhamento (evita o corte do texto)
  function replaceDivBlock(htmlStr, className, replacement) {
    let regex = new RegExp(`<div[^>]*class="[^"]*${className}[^"]*"`, 'gi');
    let match;

    while ((match = regex.exec(htmlStr)) !== null) {
      let start = match.index;
      let end = start + match[0].length;
      let openDivs = 1; // Já conta a div principal que abriu o bloco

      // Procura pelas próximas tags div (abrindo ou fechando)
      let tagRegex = /<\/?div[^>]*>/gi;
      tagRegex.lastIndex = end;

      let tagMatch;
      while ((tagMatch = tagRegex.exec(htmlStr)) !== null) {
        if (tagMatch[0].toLowerCase().startsWith('</div')) {
          openDivs--;
        } else {
          openDivs++;
        }

        // Quando zerar as divs abertas, achamos o fim exato do bloco
        if (openDivs === 0) {
          end = tagMatch.index + tagMatch[0].length;
          break;
        }
      }

      // Substitui o bloco exato e mantém o restante do texto intacto
      let before = htmlStr.substring(0, start);
      let after = htmlStr.substring(openDivs === 0 ? end : htmlStr.length);
      htmlStr = before + replacement + after;

      // Ajusta o cursor do regex para continuar procurando outros blocos
      regex.lastIndex = start + replacement.length;
    }
    return htmlStr;
  }

  // 1. Detecta e substitui TABELAS COMPARATIVAS
  html = html.replace(/<table[\s\S]*?<\/table>/gi, '\n\nVeja a tabela comparativa de valores e custos completa em nosso site.\n\n');

  // 2. Detecta e substitui FICHAS TÉCNICAS (.ficha-tecnica) - Usando a função inteligente
  html = replaceDivBlock(html, 'ficha-tecnica', '\n\nConfira a ficha técnica detalhada no nosso site.\n\n');

  // 3. Detecta e substitui CAIXAS DE PRÓS E CONTRAS (.box-pros-cons) - Usando a função inteligente
  html = replaceDivBlock(html, 'box-pros-cons', '\n\nConfira a lista completa de prós e contras em nosso site.\n\n');

  // 4. Converte BLOCKQUOTES (Dicas/Alertas) em avisos narrados
  html = html.replace(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi, (match, conteudo) => {
    let textoLimpo = conteudo.replace(/<[^>]+>/g, '').trim();
    return `\n\nAtenção para a dica da oficina: ${textoLimpo}\n\n`;
  });

  // 5. Converte Títulos (H2, H3) em frases com pontuação final para pausa na leitura
  html = html.replace(/<h[2-4][^>]*>([\s\S]*?)<\/h[2-4]>/gi, (match, tituloBloco) => {
    let t = tituloBloco.replace(/<[^>]+>/g, '').trim();
    if (!/[.!?:]$/.test(t)) t += '.';
    return `\n\n${t}\n\n`;
  });

  // 6. Trata quebras de parágrafos e itens de listas
  html = html.replace(/<\/p>/gi, '\n');
  html = html.replace(/<\/li>/gi, '.\n');

  // 7. Remove todas as tags HTML restantes
  let textoLimpo = html.replace(/<[^>]+>/g, '');

  // 8. Decodifica entidades HTML
  textoLimpo = textoLimpo
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, ' e ')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/<code>/g, '')
    .replace(/<\/code>/g, '');

  // 9. Normaliza espaços múltiplos e quebras de linha
  textoLimpo = textoLimpo
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n\n')
    .trim();

  // Vincula a introdução com o texto limpo
  const introAudio = `Você está ouvindo o artigo: ${titulo}. No portal Moto na Prática.\n\n`;
  return introAudio + textoLimpo;
}

// --- EXECUÇÃO ---
const inputData = $input.item.json;
let titulo = "";
let blocosHtml = [];

// Extração do título e blocos
if (inputData.payload_para_api && inputData.payload_para_api.output && inputData.payload_para_api.output.pt) {
  const pt = inputData.payload_para_api.output.pt;
  titulo = pt.title || "";

  const blockKeys = Object.keys(pt)
    .filter(k => k.startsWith("block-"))
    .sort((a, b) => parseInt(a.replace("block-", "")) - parseInt(b.replace("block-", "")));

  blocosHtml = blockKeys.map(k => pt[k]);
} else if (inputData.blocos_originais && Array.isArray(inputData.blocos_originais)) {
  titulo = inputData.title || (inputData.payload_para_api && inputData.payload_para_api.output.pt.title) || "";
  blocosHtml = inputData.blocos_originais.map(b => b.html_do_bloco || "");
}

const textoFinalTts = converterHtmlParaTextoTts(titulo, blocosHtml);

// Retorna APENAS tts_text
return {
  json: {
    tts_text: textoFinalTts
  }
};

